mapper.select:
SELECT w.WRITE_OFF_ID as writeOffId, w.WRITE_OFF_NO as writeOffNo, w.WRITE_OFF_AMOUNT as writeOffAmount, w.WRITE_OFF_STATUS as writeOffStatus, w.WRITE_OFF_DATE as writeOffDate, w.SUMMARY as summary, w.REMARKS as remarks, w.CREATE_TIME as createTime, w.CREATE_BY as createBy, p.PAYMENT_NO as paymentNo, d.DOCUMENT_NO as payableNo, s.SUPPLIER_NAME as supplierName FROM TBL_WRITE_OFF_RECORD w LEFT JOIN TBL_PAYMENT_ORDER p ON w.PAYMENT_ID = p.PAYMENT_ID AND p.IS_DELETED = 0 LEFT JOIN TBL_PAYABLE_DOCUMENT d ON w.DOCUMENT_ID = d.DOCUMENT_ID AND d.IS_DELETED = 0 LEFT JOIN TBL_SUPPLIER s ON p.SUPPLIER_ID = s.SUPPLIER_ID AND s.IS_DELETED = 0 WHERE w.IS_DELETED = 0
AND w.WRITE_OFF_NO LIKE '%' || #{param.writeOffNo} || '%'
AND p.SUPPLIER_ID = #{param.supplierId}
AND w.WRITE_OFF_STATUS = #{param.writeOffStatus}
ORDER BY w.CREATE_TIME DESC OFFSET #{offset} ROWS FETCH NEXT #{pageSize} ROWS ONLY

SELECT COUNT(1) FROM TBL_WRITE_OFF_RECORD w LEFT JOIN TBL_PAYMENT_ORDER p ON w.PAYMENT_ID = p.PAYMENT_ID AND p.IS_DELETED = 0 WHERE w.IS_DELETED = 0
AND w.WRITE_OFF_NO LIKE '%' || #{param.writeOffNo} || '%'
AND p.SUPPLIER_ID = #{param.supplierId}
AND w.WRITE_OFF_STATUS = #{param.writeOffStatus}
